@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_d07a82e473ff447da5db54c089885df9.Services
@inject RecipeService RecipeService
@inject ILogger<Recipes> Logger
@implements IAsyncDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex justify-content-between align-items-center" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}

@if (_recipes is null && _isLoading)
{
    <p><em>Loading recipes…</em></p>
}
else if (_recipes is not null)
{
    @if (_isLoading)
    {
        <div class="text-muted mb-2"><small>Refreshing…</small></div>
    }

    @if (_recipes.Count == 0)
    {
        <p>No recipes found for this cuisine.</p>
    }
    else
    {
        <table class="table">
            <thead>
                <tr>
                    <th>Title</th>
                    <th>Description</th>
                    <th>Prep Time (min)</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var recipe in DisplayedRecipes)
                {
                    <tr>
                        <td>@recipe.Title</td>
                        <td>@recipe.Description</td>
                        <td>@recipe.PrepTimeMinutes</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isLoading;
    private string? _errorMessage;

    private int _loadedCuisineId;
    private CancellationTokenSource? _loadCts;
    private CancellationTokenSource _disposeCts = new();

    private IReadOnlyList<Recipe> DisplayedRecipes =>
        string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? _recipes!.OrderByDescending(r => r.Id).ToList()
            : string.Equals(Sort, "newest", StringComparison.OrdinalIgnoreCase)
                ? _recipes!.OrderByDescending(r => r.PrepTimeMinutes).ToList()
                : _recipes!;

    protected override Task OnParametersSetAsync()
    {
        if (CuisineId == _loadedCuisineId)
        {
            // Only sort changed — no reload needed.
            return Task.CompletedTask;
        }

        return LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load for the previous cuisine.
        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }

        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);
        var cts = _loadCts;

        _isLoading = true;
        _errorMessage = null;
        _loadedCuisineId = CuisineId;

        try
        {
            var recipes = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);

            if (cts.Token.IsCancellationRequested)
            {
                return;
            }

            _recipes = recipes;
        }
        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
        {
            // Load was superseded or the component is disposing — do nothing.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            if (!cts.Token.IsCancellationRequested)
            {
                _isLoading = false;
            }
        }
    }

    private Task RetryAsync()
    {
        _loadedCuisineId = 0; // Force reload.
        return LoadRecipesAsync();
    }

    public async ValueTask DisposeAsync()
    {
        await _disposeCts.CancelAsync();

        if (_loadCts is not null)
        {
            await _loadCts.CancelAsync();
            _loadCts.Dispose();
        }

        _disposeCts.Dispose();
    }
}

